  "sv.mfa_off_done": { pt: "A entrada em dois passos foi desligada.", en: "Two-step sign-in has been turned off.", zh: "两步登录已关闭。" },
  "sv.mfa_title": { pt: "Entrar em dois passos", en: "Two-step sign-in", zh: "两步登录" },
  "sv.mfa_intro": { pt: "Proteja a sua conta: além da palavra-passe, para entrar é preciso um código de 6 algarismos que muda a cada 30 segundos, mostrado por uma APP no seu telemóvel. Mesmo que alguém descubra a palavra-passe, não consegue entrar sem o seu telemóvel.", en: "Protect your account: besides the password, signing in requires a 6-digit code that changes every 30 seconds, shown by an app on your phone. Even if someone finds out your password, they can't sign in without your phone.", zh: "保护您的账户：除密码外，登录还需要手机应用显示的 6 位验证码，每 30 秒更新一次。即使有人知道您的密码，没有您的手机也无法登录。" },
